function invPenSearch(string $text,int $page=1):array{
if(mb_strlen(trim($text))<2||mb_strlen($text)>150||$page<1||$page>100)throw new InvalidArgumentException('Texto de 2–150 caracteres y página 1–100.');
$url='https://estadonacion.or.cr/wp-json/wp/v2/search?'.http_build_query(['search'=>$text,'page'=>$page,'per_page'=>10]);$r=invHttp($url);$data=json_decode($r['body'],true,512,JSON_THROW_ON_ERROR);if(!is_array($data)||!array_is_list($data))throw new RuntimeException('Respuesta PEN inesperada.');$out=[];
foreach($data as $d)if(isset($d['url'])&&invAllowed($d['url']))$out[]=['titulo'=>html_entity_decode(strip_tags((string)$d['title']),ENT_QUOTES|ENT_HTML5,'UTF-8'),'url'=>$d['url'],'tipo'=>$d['subtype']??'publicacion'];
return ['resultados'=>$out,'pagina'=>$page,'limite'=>10,'hay_mas_posible'=>count($data)===10,'consultado_en'=>gmdate('c'),'fuente'=>$url,'alcance'=>'Índice público del sitio PEN; no busca dentro de todos los archivos ni visualizadores.','reglas'=>INV_REGLAS];
}
function invPenRead(string $url,int $part=1):array{
if(!invAllowed($url)||!in_array(parse_url($url,PHP_URL_HOST),['estadonacion.or.cr','www.estadonacion.or.cr','estadisticas.estadonacion.or.cr'],true))throw new InvalidArgumentException('Use una URL oficial PEN del catálogo o búsqueda.');
$r=invHttp($url);$body=$r['body'];$text='';$links=[];$format='html';$rows=null;$dates=[];
if(str_starts_with($body,'%PDF')){$format='pdf';$text=drivePdfText($body);}
elseif(str_starts_with($body,'PK')){$format='xlsx';$rows=invXlsxRows($body);}
elseif(str_contains($r['mime'],'csv')||preg_match('/\.csv$/i',parse_url($url,PHP_URL_PATH)??'')){$format='csv';$rows=[];$stream=fopen('php://temp','r+');fwrite($stream,$body);rewind($stream);while(($row=fgetcsv($stream,0,',','"',''))!==false){$rows[]=$row;if(count($rows)>100000){fclose($stream);throw new RuntimeException('CSV demasiado grande.');}}fclose($stream);}
elseif(str_contains($r['mime'],'html')){$dom=new DOMDocument();$old=libxml_use_internal_errors(true);try{$dom->loadHTML('<?xml encoding="UTF-8">'.$body,LIBXML_NONET);}finally{libxml_clear_errors();libxml_use_internal_errors($old);}$xp=new DOMXPath($dom);foreach($xp->query('//meta[@property="article:published_time" or @property="article:modified_time"]') as $m)$dates[$m->getAttribute('property')]=$m->getAttribute('content');foreach($xp->query('//script|//style|//nav|//header|//footer|//noscript') as $n)$n->parentNode->removeChild($n);$root=$xp->query('//main')->item(0)??$xp->query('//body')->item(0);if($root){foreach($xp->query('.//a[@href]',$root) as $a){$href=html_entity_decode($a->getAttribute('href'),ENT_QUOTES|ENT_HTML5,'UTF-8');if(str_starts_with($href,'/'))$href='https://'.parse_url($url,PHP_URL_HOST).$href;if(invAllowed($href))$links[$href]=['titulo'=>trim($a->textContent),'url'=>$href];}foreach($xp->query('.//p|.//tr|.//li|.//h1|.//h2|.//h3',$root) as $n)$n->appendChild($dom->createTextNode("\n"));$text=trim(preg_replace('/[\t ]+/u',' ',$root->textContent));}}
else throw new RuntimeException('Formato no soportado. Abra el original oficial.');
$parts=$rows!==null?max(1,(int)ceil(count($rows)/50)):max(1,(int)ceil(mb_strlen($text)/14000));if($part<1||$part>$parts)throw new InvalidArgumentException('Parte fuera de rango 1–'.$parts);
return ['url'=>$url,'fechas_publicadas'=>$dates,'formato'=>$format,'consultado_en'=>gmdate('c'),'parte'=>$part,'partes'=>$parts,'texto'=>mb_substr($text,($part-1)*14000,14000),'filas'=>$rows!==null?array_slice($rows,($part-1)*50,50):null,'total_filas'=>$rows!==null?count($rows):null,'documentos'=>array_slice(array_values($links),0,100),'requiere_lectura_visual'=>$rows===null&&mb_strlen($text)<200,'aviso'=>'Tablas originales sin interpretación: las fechas XLSX pueden ser seriales y las unidades/períodos deben leerse en el documento. Un portal JavaScript vacío no implica ausencia de datos.','reglas'=>INV_REGLAS];
}
function invBccrCatalog():array{return ['fuente'=>'https://sdd.bccr.fi.cr/es/IndicadoresEconomicos/Inicio/','documentacion'=>'https://gee.bccr.fi.cr/indicadoreseconomicos/Documentos/DocumentosMetodologiasNotasTecnicas/Estandar_API_SDDE.pdf','temas_inversion'=>['tipo de cambio y riesgo cambiario','inflación y poder adquisitivo','tasas de interés y financiamiento','actividad económica y PIB','sector externo y reservas','crédito y condiciones financieras'],'requiere'=>'Token Bearer SDDE por usuario, guardado en Conectores → BCCR. No enviar por chat.','flujo'=>'bccr_buscar consulta el catálogo oficial vigente XLSX; use su código en bccr_indicador. No se usan códigos heredados inferidos.','reglas'=>INV_REGLAS];}
function invBccrToken(array $user):string{$c=connectorGet((int)$user['id'],'bccr');$token=trim((string)($c['token']??''));if($token==='')throw new RuntimeException('Configure el token SDDE en Conectores → BCCR. Las fuentes públicas están en bccr_fuentes; no hay valores simulados.');return $token;}
function invBccrJson(array $user,string $path,array $query):array{$url=INV_BCCR_BASE.$path.'?'.http_build_query($query);$r=invHttp($url,invBccrToken($user));$d=json_decode($r['body'],true,512,JSON_THROW_ON_ERROR|JSON_BIGINT_AS_STRING);if(!is_array($d)||($d['estado']??false)!==true||!is_array($d['datos']??null))throw new RuntimeException('El BCCR no devolvió una consulta exitosa; no se generaron valores.');return ['datos'=>$d['datos'],'url'=>$url];}
function invBccrSearch(array $user,string $text,int $offset=0):array{if(mb_strlen(trim($text))<2||mb_strlen($text)>150||$offset<0||$offset>100000)throw new InvalidArgumentException('Consulta o desplazamiento inválido.');$url=INV_BCCR_BASE.'/indicadoresEconomicos/descargar?idioma=ES';$r=invHttp($url,invBccrToken($user));$rows=invXlsxRows($r['body']);$matches=array_values(array_filter($rows,static fn($r)=>str_contains(invFold(implode(' ',$r['celdas'])),invFold($text))));return ['filas'=>array_slice($matches,$offset,50),'encabezado_original'=>array_slice($rows,0,5),'total_coincidencias'=>count($matches),'desplazamiento'=>$offset,'limite'=>50,'fuente'=>$url,'consultado_en'=>gmdate('c'),'reglas'=>INV_REGLAS];}
function invDate(string $s):DateTimeImmutable{$d=DateTimeImmutable::createFromFormat('!Y-m-d',$s);if(!$d||$d->format('Y-m-d')!==$s)throw new InvalidArgumentException('Fecha inválida; use AAAA-MM-DD.');return $d;}
function invBccrIndicator(array $user,int $code,string $start,string $end,int $offset=0,int $limit=100):array{
if($code<1||$code>10000000||$offset<0||$offset>100000||$limit<1||$limit>500)throw new InvalidArgumentException('Código o paginación inválida.');$a=invDate($start);$b=invDate($end);if($a>$b||$a->diff($b)->days>3660)throw new InvalidArgumentException('Rango inválido o mayor a diez años.');
$meta=invBccrJson($user,'/indicadoresEconomicos/'.$code.'/metadata',['idioma'=>'ES']);$series=invBccrJson($user,'/indicadoresEconomicos/'.$code.'/series',['fechaInicio'=>$a->format('Y/m/d'),'fechaFin'=>$b->format('Y/m/d'),'idioma'=>'ES']);$rows=[];foreach($series['datos'] as $s){if((string)($s['codigoIndicador']??'')!==(string)$code)throw new RuntimeException('El código recibido no coincide.');foreach($s['series']??[] as $point)$rows[]=$point;}
return ['codigo'=>$code,'metadata'=>$meta['datos'],'serie'=>array_slice($rows,$offset,$limit),'total_observaciones'=>count($rows),'desplazamiento'=>$offset,'limite'=>$limit,'rango'=>[$start,$end],'fuentes'=>[$meta['url'],$series['url']],'consultado_en'=>gmdate('c'),'reglas'=>INV_REGLAS];
}
function invTools():array{$ro=['readOnlyHint'=>true,'destructiveHint'=>false,'idempotentHint'=>true,'openWorldHint'=>true];$tools=[];$add=static function($n,$d,$p=[],$req=[])use(&$tools,$ro){$tools[]=['name'=>$n,'description'=>$d,'annotations'=>$ro,'inputSchema'=>['type'=>'object','properties'=>(object)$p,'required'=>$req]];};
