$add('bccr_indicador','Consulta metadata y serie oficiales BCCR por código obtenido del catálogo vigente, con fechas, unidades originales y paginación. Requiere token; sin cálculos ni pronósticos del MCP.',['codigo'=>['type'=>'integer','minimum'=>1,'maximum'=>10000000],'desde'=>['type'=>'string','description'=>'AAAA-MM-DD'],'hasta'=>['type'=>'string','description'=>'AAAA-MM-DD'],'desplazamiento'=>['type'=>'integer','minimum'=>0,'maximum'=>100000],'limite'=>['type'=>'integer','minimum'=>1,'maximum'=>500]],['codigo','desde','hasta']);return $tools;}
